export interface Product {
  id: number;
  name: string;
  img?: string;
  comment?: string;
}

export interface Item {
  id: number;
  product: Product;
  count: number;
  groupColor?: string;
  status: ItemStatus;
}

export enum ItemStatus {
  ToBuy = 'to_buy',
  Bought = 'bought'
}

export type CreateItemFields = Omit<Item, 'id' | 'product'> & { product: Omit<Product, 'id'> };
export type UpdateItemFields = Partial<Omit<Item, 'id' | 'product'>>;

export interface List {
  id: number;
  name: string;
  comment?: string;
  img?: string;
  items: Item[];
}

export type CreateListFields = Omit<List, 'id' | 'items'>;
export type UpdateListFields = Partial<Omit<List, 'id' | 'items'>>;
